<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support inbox · eRPH Pro</title><style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc;--green:#166534}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px/1.55 Inter,system-ui,sans-serif}a{color:inherit}.shell{max-width:1240px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:30px}.brand,.top a{color:inherit;text-decoration:none}.brand{font-weight:800}.top a{color:var(--muted)}.intro{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px}.intro h1{margin:0;font-size:36px;letter-spacing:-.05em}.muted{color:var(--muted)}.filters{display:flex;gap:10px;flex-wrap:wrap}.filters a,.pill{display:inline-flex;padding:7px 11px;border:1px solid var(--line);border-radius:99px;text-decoration:none;background:#fff;font-size:13px}.inbox{overflow:hidden;border:1px solid var(--line);border-radius:18px;background:#fff}.row{display:grid;grid-template-columns:1.3fr 1fr .7fr .7fr;gap:16px;align-items:center;padding:17px 20px;border-top:1px solid var(--line)}.row:first-child{border-top:0}.row.head{background:#fbfcfe;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}.subject{font-weight:750;text-decoration:none}.requester{color:var(--muted);font-size:13px}.status{font-size:12px;font-weight:750;text-transform:capitalize}.status.open{color:var(--blue)}.status.pending{color:#92400e}.status.resolved,.status.closed{color:var(--green)}.ai{font-size:12px;color:var(--muted)}@media(max-width:760px){.shell{padding:20px}.row{grid-template-columns:1fr;gap:5px}.row.head{display:none}.intro{align-items:flex-start;flex-direction:column}}</style></head><body><div class="shell"><header class="top"><a class="brand" href="{{ route('owner.dashboard') }}">eRPH Pro · Owner console</a><a href="{{ route('owner.dashboard') }}">Back to dashboard</a></header><section class="intro"><div><p class="muted">Customer communication</p><h1>Support inbox</h1><p class="muted">Review AI triage, reply to requesters and keep sensitive decisions human-led.</p></div><div class="filters"><a href="{{ route('owner.support.index') }}">All tickets</a><a href="{{ route('owner.support.index', ['status' => 'open']) }}">Open</a><a href="{{ route('owner.support.index', ['status' => 'pending']) }}">Pending</a></div></section><section class="inbox"><div class="row head"><div>Ticket</div><div>Requester</div><div>Status</div><div>Priority</div></div>@forelse($tickets as $ticket)<div class="row"><div><a class="subject" href="{{ route('owner.support.show', $ticket->public_id) }}">Ticket {{ $ticket->public_id }}</a><div class="requester">School-approved access</div></div><div>School-approved ticket</div><div class="status {{ $ticket->status }}">{{ $ticket->status }}</div><div><span class="pill">{{ $ticket->priority }}</span></div></div>@empty<div class="row"><div>No support tickets yet.</div></div>@endforelse</section><div style="margin-top:22px">{{ $tickets->links() }}</div></div></body></html>
